<?php
namespace ExcelHerbal\ERP7\Organization;
use ExcelHerbal\ERP7\Security\DesignationDefaults;use ExcelHerbal\ERP7\Core\Input;use ExcelHerbal\ERP7\Database\Db;use ExcelHerbal\ERP7\Database\Transaction;use ExcelHerbal\ERP7\Domain\DomainException;use ExcelHerbal\ERP7\Security\Actor;use ExcelHerbal\ERP7\Security\Audit;use ExcelHerbal\ERP7\Security\BranchAuthority;use ExcelHerbal\ERP7\Security\Capabilities;use ExcelHerbal\ERP7\Security\Guard;use ExcelHerbal\ERP7\Security\HierarchyScope;
final class OrganizationMasterDataService{
 public static function designations(Actor $a):array{Guard::any($a,[Capabilities::EMP_VIEW,Capabilities::EMP_MANAGE,Capabilities::HR_MANAGE]);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT id,code,name,sequence_no,field_role,status FROM ".Db::table('designations')." WHERE company_id=%d AND status='active' ORDER BY sequence_no,name",$a->companyId),ARRAY_A);}
 public static function roles(Actor $a):array{Guard::cap($a,Capabilities::ACCESS_MANAGE);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT id,code,name FROM ".Db::table('roles')." WHERE company_id=%d AND active=1 ORDER BY name",$a->companyId),ARRAY_A);}
 public static function masterData(Actor $a):array{Guard::cap($a,Capabilities::ACCESS);$db=Db::wpdb();$revisions=Db::table('product_commercial_revisions');$now=Db::now();$p=(array)$db->get_results($db->prepare("SELECT p.id,p.sku,p.name,p.uom,p.batch_tracking,p.expiry_tracking,(SELECT cr.points FROM {$revisions} cr WHERE cr.company_id=p.company_id AND cr.product_id=p.id AND cr.status='active' AND cr.effective_from<=%s ORDER BY cr.effective_from DESC,cr.id DESC LIMIT 1) points FROM ".Db::table('products')." p WHERE p.company_id=%d AND p.status='active' ORDER BY p.name",$now,$a->companyId),ARRAY_A);$s=(array)$db->get_results($db->prepare("SELECT id,name,mobile,gstin FROM ".Db::table('suppliers')." WHERE company_id=%d AND status='active' ORDER BY name",$a->companyId),ARRAY_A);$acc=(array)$db->get_results($db->prepare("SELECT id,code,name,type,subtype FROM ".Db::table('accounts')." WHERE company_id=%d AND active=1 ORDER BY code",$a->companyId),ARRAY_A);return['products'=>$p,'suppliers'=>$s,'accounts'=>$acc];}
}
